def min_distance_brute(word1, word2, i, j):
    if i == len(word1):
        return len(word2) - j                                # insert remaining word2 characters
    if j == len(word2):
        return len(word1) - i                                # delete remaining word1 characters
    if word1[i] == word2[j]:
        return min_distance_brute(word1, word2, i + 1, j + 1)   # free skip
    replace = 1 + min_distance_brute(word1, word2, i + 1, j + 1)
    delete = 1 + min_distance_brute(word1, word2, i + 1, j)
    insert = 1 + min_distance_brute(word1, word2, i, j + 1)
    return min(replace, delete, insert)                     # try ALL THREE operations

